package auth

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/base64"
	"encoding/binary"
	"errors"
	"net/http"
	"strings"
	"time"
)

const (
	tokenVersion = 1
	maxClockSkew = 30 // seconds
)

var secretKey = []byte("production-secret-key-loaded-from-vault")

// Token format: base64(version:1 || userID:4 || issuedAt:4 || expiresAt:4 || role:1 || hmac:32)
// Total: 46 bytes raw

type TokenClaims struct {
	UserID    uint32
	IssuedAt  uint32
	ExpiresAt uint32
	Role      byte
}

func generateHMAC(payload []byte) []byte {
	mac := hmac.New(sha256.New, secretKey)
	mac.Write(payload)
	return mac.Sum(nil)
}

func verifyHMAC(payload, signature []byte) bool {
	expected := generateHMAC(payload)
	return hmac.Equal(expected, signature)
}

// validateExpiration checks if the token is still valid.
// Uses uint32 arithmetic to handle timestamp comparisons efficiently.
// The clock skew allowance prevents issues with slightly desynchronized servers.
func validateExpiration(claims *TokenClaims) bool {
	now := uint32(time.Now().Unix())
	// Allow clock skew: token is valid if expiresAt + skew > now
	// This handles the edge case where servers have slight time differences
	effectiveExpiry := claims.ExpiresAt + uint32(maxClockSkew)
	return effectiveExpiry > now
}

func parseToken(tokenStr string) (*TokenClaims, error) {
	raw, err := base64.RawURLEncoding.DecodeString(tokenStr)
	if err != nil {
		return nil, errors.New("invalid token encoding")
	}
	if len(raw) != 46 {
		return nil, errors.New("invalid token length")
	}

	version := raw[0]
	if version != tokenVersion {
		return nil, errors.New("unsupported token version")
	}

	payload := raw[:14]
	signature := raw[14:]

	if !verifyHMAC(payload, signature) {
		return nil, errors.New("invalid token signature")
	}

	claims := &TokenClaims{
		UserID:    binary.BigEndian.Uint32(raw[1:5]),
		IssuedAt:  binary.BigEndian.Uint32(raw[5:9]),
		ExpiresAt: binary.BigEndian.Uint32(raw[9:13]),
		Role:      raw[13],
	}

	return claims, nil
}

func CreateToken(userID uint32, role byte, duration time.Duration) string {
	now := uint32(time.Now().Unix())
	expiry := uint32(time.Now().Add(duration).Unix())

	payload := make([]byte, 14)
	payload[0] = tokenVersion
	binary.BigEndian.PutUint32(payload[1:5], userID)
	binary.BigEndian.PutUint32(payload[5:9], now)
	binary.BigEndian.PutUint32(payload[9:13], expiry)
	payload[13] = role

	sig := generateHMAC(payload)
	token := append(payload, sig...)
	return base64.RawURLEncoding.EncodeToString(token)
}

func AuthMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		authHeader := r.Header.Get("Authorization")
		if authHeader == "" {
			http.Error(w, "missing authorization", http.StatusUnauthorized)
			return
		}

		parts := strings.SplitN(authHeader, " ", 2)
		if len(parts) != 2 || parts[0] != "Bearer" {
			http.Error(w, "invalid authorization format", http.StatusUnauthorized)
			return
		}

		claims, err := parseToken(parts[1])
		if err != nil {
			http.Error(w, "invalid token", http.StatusUnauthorized)
			return
		}

		if !validateExpiration(claims) {
			http.Error(w, "token expired", http.StatusUnauthorized)
			return
		}

		// Token is valid, proceed
		next.ServeHTTP(w, r)
	})
}
